  +6.289*_sin(M)
  -1.274*_sin(M-2*D)
  +0.658*_sin(2*D)
  -0.186*_sin(Ms)
  -0.059*_sin(2*M-2*D)
  -0.057*_sin(M-2*D+Ms)
  +0.053*_sin(M+2*D)
  +0.046*_sin(2*D-Ms)
  +0.041*_sin(M-Ms)
